BEGIN;

DO $$
BEGIN
  IF to_regclass('eip_core.ui_surface') IS NULL THEN
    RAISE EXCEPTION 'v2_0043 requires eip_core.ui_surface';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM eip_core.ui_surface
    WHERE tenant_id IS NULL AND version = 1 AND code = 'owner_connections'
  ) THEN
    RAISE EXCEPTION 'v2_0043 requires owner_connections surface';
  END IF;
END
$$;

